import sys
import json
import argparse
import re
import os
from datetime import datetime

def get_config():
    config = {
        "message_keys": ["short_message", "msg", "message"],
        "time_keys": ["timestamp", "time", "@timestamp"],
        "dump_all_exclude": [],
        "always_print_fields": [],
        "level_keys": ["level", "severity", "log.level", "loglevel"],
        "main_line_format": "{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}",
        "additional_value_format": "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}",
        "level_map": {}
    }

    # Try to load from default locations
    # 1. ~/.config/fblog/fblog.toml
    # 2. /etc/fblog/fblog.toml
    # For now, let's just stick to defaults unless --config-file is used.
    return config

def load_toml(path):
    try:
        import tomli
        with open(path, "rb") as f:
            return tomli.load(f)
    except:
        return {}

def parse_args():
    parser = argparse.ArgumentParser(description="json log viewer")
    parser.add_argument("input", nargs="?", default="-")
    parser.add_argument("-a", "--additional-value", action="append")
    parser.add_argument("--config-file")
    parser.add_argument("-m", "--message-key", action="append")
    parser.add_argument("-t", "--time-key", action="append")
    parser.add_argument("-l", "--level-key", action="append")
    parser.add_argument("--map-level", action="append")
    parser.add_argument("-d", "--dump-all", action="store_true")
    parser.add_argument("-x", "--excluded-value", action="append")
    parser.add_argument("-p", "--with-prefix", action="store_true")
    parser.add_argument("-f", "--filter")
    parser.add_argument("--no-implicit-filter-return-statement", action="store_true")
    parser.add_argument("--main-line-format")
    parser.add_argument("--additional-value-format")
    parser.add_argument("-s", "--substitute", action="store_true")
    parser.add_argument("-c", "--context-key")
    parser.add_argument("-F", "--placeholder-format")
    parser.add_argument("-V", "--version", action="version", version="fblog 0.3.5")
    return parser.parse_args()

def get_nested(data, path):
    parts = path.split(" > ")
    for p in parts:
        if isinstance(data, dict) and p in data:
            data = data[p]
        else:
            return None
    return data

def apply_style(text, style):
    return f"\x1b[{style}m{text}\x1b[0m"

def bold(text): return apply_style(text, "1")
def cyan(text): return apply_style(text, "36")
def red(text): return apply_style(text, "31")
def green(text): return apply_style(text, "32")
def yellow(text): return apply_style(text, "33")
def blue(text): return apply_style(text, "34")
def magenta(text): return apply_style(text, "35")
def color_rgb(r, g, b, text): return f"\x1b[38;2;{r};{g};{b}m{text}\x1b[0m"
def faint(text): return apply_style(text, "2")

def level_style(level):
    level = level.strip().lower()
    styles = {
        "info": "1;32",
        "warn": "1;33",
        "error": "1;31",
        "debug": "1;34",
        "fatal": "1;35",
        "trace": "1;36",
    }
    style = styles.get(level, "1;35")
    return apply_style(level.upper().rjust(5), style)

def fixed_size(n, text):
    text = str(text)
    if len(text) > n: return text[:n]
    return text.rjust(n)

def min_size(n, text):
    text = str(text)
    if len(text) >= n: return text
    return text.rjust(n)

def format_value_substitution(val):
    if isinstance(val, bool):
        return bold(green("true") if val else red("false"))
    if isinstance(val, (int, float)):
        return bold(cyan(str(val)))
    if isinstance(val, str):
        return bold(yellow(val))
    if isinstance(val, list):
        items = [format_value_substitution(i) for i in val]
        return faint("[") + faint(", ").join(items) + faint("]")
    if isinstance(val, dict):
        items = []
        for k in sorted(val.keys()):
            items.append(magenta(k) + faint(": ") + format_value_substitution(val[k]))
        return faint("{") + faint(", ").join(items) + faint("}")
    return str(val)

def substitute(message, context, placeholder_format):
    if not placeholder_format or "key" not in placeholder_format:
        return message

    if isinstance(context, dict):
        for k, v in context.items():
            placeholder = placeholder_format.replace("key", k)
            if placeholder in message:
                message = message.replace(placeholder, format_value_substitution(v))
    elif isinstance(context, list):
        for i, v in enumerate(context):
            placeholder = placeholder_format.replace("key", str(i))
            if placeholder in message:
                message = message.replace(placeholder, format_value_substitution(v))
    return message

# Placeholder for template engine
def render_template(template, context):
    # Very simple Handlebars-like parser
    # Handle {{#if ...}} ... {{/if}}
    while True:
        match = re.search(r'\{\{#if\s+(.*?)\}\}(.*?)\{\{/if\}\}', template, re.DOTALL)
