        # Simple split but respect nested parentheses (not needed for now)
        parts = expr.split()
        if len(parts) > 1:
            # Check if parts[0] is a helper
            if parts[0] in HELPERS:
                helper = parts[0]
                # If there are multiple arguments, some might be numbers
                # e.g. fixed_size 19 fblog_timestamp
                if helper == "fixed_size" and len(parts) >= 3:
                    n = int(parts[1])
                    val = eval_expr(" ".join(parts[2:]))
                    return fixed_size(n, val)
                if helper == "min_size" and len(parts) >= 3:
                    n = int(parts[1])
                    val = eval_expr(" ".join(parts[2:]))
                    return min_size(n, val)
                if helper == "color_rgb" and len(parts) >= 5:
                    r, g, b = parts[1:4]
                    val = eval_expr(" ".join(parts[4:]))
                    return color_rgb(r, g, b, val)

                val = eval_expr(" ".join(parts[1:]))
                return apply_helper(helper, val)

        # Otherwise it's a variable
        return str(context.get(expr, ""))

    HELPERS = ["bold", "cyan", "uppercase", "level_style", "fixed_size", "min_size", "color_rgb"]

    def apply_helper(helper, val):
        if helper == "bold": return bold(val)
        if helper == "cyan": return cyan(val)
        if helper == "uppercase": return val.upper()
        if helper == "level_style": return level_style(val)
        # others handled in eval_expr
        return val

