    if args.message_key: config["message_keys"] = args.message_key + config["message_keys"]
    if args.time_key: config["time_keys"] = args.time_key + config["time_keys"]
    if args.level_key: config["level_keys"] = args.level_key + config["level_keys"]
    if args.main_line_format: config["main_line_format"] = args.main_line_format
    if args.additional_value_format: config["additional_value_format"] = args.additional_value_format
    if args.excluded_value: config["dump_all_exclude"] += args.excluded_value

    level_map = config["level_map"]
    if args.map_level:
        for m in args.map_level:
            if "=" in m:
                f, t = m.split("=", 1)
                level_map[f] = t

