        for k in config["time_keys"]:
            val = get_nested(data, k)
            if val is not None:
                # Handle unix timestamp
                if isinstance(val, (int, float)):
                    # milliseconds?
                    if val > 1e11: val /= 1000
                    try:
                        dt = datetime.fromtimestamp(val)
                        fblog_timestamp = dt.isoformat()
                    except:
                        fblog_timestamp = str(val)
                else:
                    fblog_timestamp = str(val)
                break

