        for k in config["level_keys"]:
            val = get_nested(data, k)
            if val is not None:
                fblog_level = str(val).lower()
                break

        fblog_level = level_map.get(fblog_level, fblog_level)

        # Substitution
        if args.substitute:
            context = get_nested(data, args.context_key) if args.context_key else None
            fblog_message = substitute(fblog_message, context, args.placeholder_format)

        # Filter
        if args.filter:
            # ... implement filter ...
            pass

        # Context for template
        context = data.copy()
        context["fblog_message"] = fblog_message
        context["fblog_timestamp"] = fblog_timestamp
        context["fblog_level"] = fblog_level
        context["fblog_prefix"] = prefix

        # Print main line
        main_line = render_template(config["main_line_format"], context)
        sys.stdout.write(main_line + "\n")

        # Dump additional values
        dump_keys = []
        if args.additional_value:
            dump_keys += args.additional_value
        if args.dump_all or args.excluded_value:
            for k in sorted(data.keys()):
                if k not in config["dump_all_exclude"]:
                    dump_keys.append(k)

        for k in dump_keys:
            val = get_nested(data, k)
            if val is not None:
                add_context = {"key": k, "value": str(val)}
                add_line = render_template(config["additional_value_format"], add_context)
                sys.stdout.write(add_line + "\n")

if __name__ == "__main__":
    main()
